"use client";

import { useEffect, useMemo, useState } from "react";
import { applyBotAction, chooseBotClaimAction, chooseBotTurnAction } from "../game/bots";
import { bestMoveOptions, explainHand, handSummary, type CoachingOption } from "../game/coaching";
import { canClaimPung, canClaimPureChow, canDeclareConcealedKong, canDeclareMahjong, claimPung, claimPureChow, declareConcealedKong, declareMahjong, discard, drawFromPile, passClaims, type EastRoundState } from "../game/state";
import { startBrowserEastRound } from "../game/session";
import { settleEastRound } from "../game/scoring";
import { createTileSet, tileLabel, type Seat, type Tile } from "../game/tiles";

const HUMAN: Seat = "east";
const seats: Seat[] = ["north", "west", "south", "east"];
const allTilesById = new Map(createTileSet().map((tile) => [tile.id, tile]));
const name = (seat: Seat) => seat === HUMAN ? "You — East" : `${seat[0].toUpperCase()}${seat.slice(1)}`;
const kindName = (kind: string) => kind === "pureChow" ? "Pure Chow" : kind[0].toUpperCase() + kind.slice(1);
function activityAfterFlowerWall(before: EastRoundState, after: EastRoundState, fallback: string) {
  if (after.flowerWall.length === before.flowerWall.length) return fallback;
  const newEvents = after.history.slice(before.history.length);
  const replacement = [...newEvents].reverse().find((event) => event.type === "drew" && event.source === "flowerWall");
  if (!replacement || replacement.type !== "drew") return fallback;
  const bonus = newEvents.find((event) => event.type === "replacedBonus" && event.seat === replacement.seat);
  const kong = newEvents.find((event) => event.type === "declaredKong" && event.seat === replacement.seat);
  const actor = name(replacement.seat);
  if (bonus) return `${actor} drew a Flower or Season, placed it in the bonus area, and took a replacement from the Flower Wall. It now has ${after.flowerWall.length} left.`;
  if (kong) return `${actor} declared a Kong, so they took the required replacement from the Flower Wall. It now has ${after.flowerWall.length} left.`;
  return `${actor} took a replacement from the Flower Wall. It now has ${after.flowerWall.length} left.`;
}
const meldTilesLabel = (kind: string, tiles: Tile[]) => {
  if ((kind === "pung" || kind === "kong") && tiles.length) return `${tileLabel(tiles[0])} ×${tiles.length}`;
  if (kind === "pureChow" && tiles.length === 3 && tiles.every((tile) => tile.kind === "number")) {
    const numbered = tiles as Array<Extract<Tile, { kind: "number" }>>;
    return `${numbered.map((tile) => tile.rank).sort((left, right) => left - right).join("–")} ${numbered[0].suit}`;
  }
  return tiles.map(tileLabel).join(" · ");
};
function tileFace(tile: Tile) {
  if (tile.kind === "number") {
    const base = tile.suit === "character" ? 0x1f007 : tile.suit === "bamboo" ? 0x1f010 : 0x1f019;
    return { glyph: String.fromCodePoint(base + tile.rank - 1), suit: tile.suit === "character" ? "萬" : tile.suit === "bamboo" ? "索" : "筒", className: `tile-${tile.suit}` };
  }
  if (tile.kind === "wind") return { glyph: String.fromCodePoint(0x1f000 + (tile.wind === "east" ? 0 : tile.wind === "south" ? 1 : tile.wind === "west" ? 2 : 3)), suit: "Wind", className: "tile-wind" };
  if (tile.kind === "dragon") return { glyph: String.fromCodePoint(0x1f004 + (tile.dragon === "red" ? 0 : tile.dragon === "green" ? 1 : 2)), suit: "Dragon", className: `tile-dragon-${tile.dragon}` };
  return { glyph: String.fromCodePoint((tile.kind === "flower" ? 0x1f022 : 0x1f026) + tile.rank - 1), suit: tile.kind === "flower" ? "Flower" : "Season", className: `tile-${tile.kind}` };
}

function TileArtwork({ tile }: { tile: Tile }) {
  const dotLayouts: Record<number, Array<[number, number]>> = {
    1: [[2, 2]], 2: [[1, 1], [3, 3]], 3: [[1, 1], [2, 2], [3, 3]], 4: [[1, 1], [3, 1], [1, 3], [3, 3]], 5: [[1, 1], [3, 1], [2, 2], [1, 3], [3, 3]], 6: [[1, 1], [3, 1], [1, 2], [3, 2], [1, 3], [3, 3]], 7: [[1, 1], [3, 1], [2, 2], [1, 3], [2, 3], [3, 3], [2, 1]], 8: [[1, 1], [2, 1], [3, 1], [1, 2], [3, 2], [1, 3], [2, 3], [3, 3]], 9: [[1, 1], [2, 1], [3, 1], [1, 2], [2, 2], [3, 2], [1, 3], [2, 3], [3, 3]],
  };
  if (tile.kind === "number" && tile.suit === "dot") return <span className={`tile-art dot-art dots-${tile.rank}`} aria-hidden="true">{dotLayouts[tile.rank].map(([column, row], index) => <i key={index} className={`dot-pip dot-${(index % 3) + 1}`} style={{ gridColumn: column, gridRow: row }} />)}</span>;
  if (tile.kind === "number" && tile.suit === "bamboo") return <span className={`tile-art bamboo-art bamboo-${tile.rank}`} aria-hidden="true">{Array.from({ length: tile.rank }, (_, index) => <i key={index} />)}</span>;
  if (tile.kind === "number" && tile.suit === "character") return <span className="tile-art character-art" aria-hidden="true"><b>{["一", "二", "三", "四", "五", "六", "七", "八", "九"][tile.rank - 1]}</b><em>萬</em></span>;
  if (tile.kind === "wind") return <span className="tile-art honour-art wind-art" aria-hidden="true">{{ east: "東", south: "南", west: "西", north: "北" }[tile.wind]}</span>;
  if (tile.kind === "dragon") return <span className={`tile-art honour-art dragon-art dragon-${tile.dragon}`} aria-hidden="true">{{ red: "中", green: "發", white: "白" }[tile.dragon]}</span>;
  return <span className={`tile-art bonus-art ${tile.kind}`} aria-hidden="true">{tile.kind === "flower" ? "✿" : "✦"}<small>{tile.rank}</small></span>;
}

function Tile({ tile, back = false, selected = false, onClick, drawn = false, compact = false, decorative = false, context = "hand", meldLabel, meldLabelOffset }: { tile?: Tile; back?: boolean; selected?: boolean; onClick?: () => void; drawn?: boolean; compact?: boolean; decorative?: boolean; context?: "hand" | "opponent" | "wall" | "discard" | "meld" | "coach"; meldLabel?: string; meldLabelOffset?: number }) {
  const face = tile && tileFace(tile);
  const className = `mahjong-tile tile-${context} ${back ? "back" : ""} ${compact ? "compact" : ""} ${face?.className ?? ""} ${selected ? "selected" : ""} ${drawn ? "drawn" : ""} ${meldLabel ? "has-meld-label" : ""}`;
  const content = <>{meldLabel && <span className="meld-badge" style={{ left: `${meldLabelOffset ?? 0}px` }}>{meldLabel}</span>}{back ? <span className="tile-back-mark">✦</span> : tile && face && <><span className="tile-index" aria-hidden="true">{tile.kind === "number" ? tile.rank : ""}</span><TileArtwork tile={tile} /><small className="tile-suit">{face.suit}</small></>}</>;
  return decorative ? <span className={className} title={tile ? tileLabel(tile) : "Concealed tile"} aria-label={tile ? tileLabel(tile) : "Concealed tile"}>{content}</span> : <button type="button" className={className} onClick={onClick} disabled={!onClick} title={tile ? tileLabel(tile) : "Concealed tile"}>{content}</button>;
}

function TileRow({ tiles, back = false, limit, selectedId, onSelect, drawnId, style, compact = false, spread = false, context = "hand", sort = false, label, labelOffset }: { tiles: Tile[]; back?: boolean; limit?: number; selectedId?: string; onSelect?: (id: string) => void; drawnId?: string; style?: React.CSSProperties; compact?: boolean; spread?: boolean; context?: "hand" | "opponent" | "wall" | "discard" | "meld"; sort?: boolean; label?: string; labelOffset?: number }) {
  const tileOrder = (tile: Tile) => tile.kind === "number" ? ({ dot: 0, bamboo: 1, character: 2 }[tile.suit] * 10 + tile.rank) : tile.kind === "wind" ? 40 + ["east", "south", "west", "north"].indexOf(tile.wind) : tile.kind === "dragon" ? 50 + ["red", "green", "white"].indexOf(tile.dragon) : tile.kind === "flower" ? 60 + tile.rank : 70 + tile.rank;
  const base = limit ? tiles.slice(0, limit) : tiles;
  const ordered = sort ? [...base].sort((left, right) => tileOrder(left) - tileOrder(right)) : base;
  const shown = drawnId ? [...ordered.filter((tile) => tile.id !== drawnId), ...ordered.filter((tile) => tile.id === drawnId)] : ordered;
  return <div className={`tile-row tile-row-${context} ${back ? "tile-row-back" : ""} ${spread ? "tile-row-spread" : ""}`} style={style}>{shown.map((tile, index) => <Tile key={tile.id} tile={tile} back={back} compact={compact} context={context} meldLabel={index === 0 ? label : undefined} meldLabelOffset={labelOffset} selected={tile.id === selectedId} drawn={tile.id === drawnId} onClick={onSelect ? () => onSelect(tile.id) : undefined} />)}</div>;
}

function CoachText({ text }: { text: string }) {
  const reference = /(?:\d(?:–\d){0,2}\s(?:Bamboo|Character|Dot)|(?:East|South|West|North)\sWind|(?:Red|Green|White)\sDragon)/g;
  const tileFor = (value: string): Tile[] => {
    const numbered = value.match(/^(\d(?:–\d){0,2})\s(Bamboo|Character|Dot)$/);
    if (numbered) return numbered[1].split("–").map((rank) => allTilesById.get(`${numbered[2].toLowerCase()}-${rank}-1`)).filter((tile): tile is Tile => !!tile);
    const wind = value.match(/^(East|South|West|North) Wind$/);
    if (wind) return [allTilesById.get(`wind-${wind[1].toLowerCase()}-1`)!];
    const dragon = value.match(/^(Red|Green|White) Dragon$/);
    if (dragon) return [allTilesById.get(`dragon-${dragon[1].toLowerCase()}-1`)!];
    return [];
  };
  const fragments = text.split(reference);
  const matches = text.match(reference) ?? [];
  return <>{fragments.flatMap((fragment, index) => index < matches.length ? [fragment, <span className="coach-inline-tiles" key={`${matches[index]}-${index}`}>{tileFor(matches[index]).map((tile) => <Tile key={tile.id} tile={tile} decorative context="coach" />)}</span>] : [fragment])}</>;
}

function Seat({ game, seat, position, onboarding, selectedId, onSelect, drawnId }: { game: EastRoundState; seat: Seat; position: string; onboarding?: boolean; selectedId?: string; onSelect?: (id: string) => void; drawnId?: string }) {
  const player = game.players[seat];
  const placement = position === "west" ? { gridColumn: 2, gridRow: 1 } : position === "east" ? { gridColumn: 2, gridRow: 3 } : position === "south" ? { gridColumn: 3, gridRow: 2 } : { gridColumn: 1, gridRow: 2 };
  const direction = position === "east" ? "column-reverse" : position === "west" ? "column" : position === "south" ? "row-reverse" : "row";
  const sideSeat = position === "north" || position === "south";
  const identityStyle: React.CSSProperties = sideSeat ? { position: "static", writingMode: "vertical-rl", transform: position === "north" ? "rotate(180deg)" : "none", flex: "0 0 18px", zIndex: 2 } : { position: "static", transform: "none", zIndex: 2 };
  const rowStyle: React.CSSProperties = { display: "flex", flexDirection: "row", gap: 0, justifyContent: "center", alignItems: "center", maxHeight: "none", overflow: "visible" };
  const rack = <div className="seat-rack" style={{ position: "static", transform: "none", width: "auto", height: "auto", display: "flex", alignItems: "center" }}><TileRow style={rowStyle} tiles={player.hand} back={seat !== HUMAN} compact={seat !== HUMAN} context={seat === HUMAN ? "hand" : "opponent"} sort={seat === HUMAN} selectedId={selectedId} drawnId={drawnId} onSelect={seat === HUMAN ? onSelect : undefined} /></div>;
  const declared = player.melds.length > 0 ? <>{player.melds.map((meld, index) => {
    const tileWidth = seat === HUMAN ? 34 : 28;
    const meldWidth = meld.tiles.length * tileWidth + Math.max(0, meld.tiles.length - 1) * 2;
    return <div key={`${meld.kind}-${index}`} className="exposed-meld"><TileRow tiles={meld.tiles} context="meld" label={kindName(meld.kind)} labelOffset={meldWidth / 2} style={{ "--meld-width": `${meldWidth}px` } as React.CSSProperties} /></div>;
  })}</> : null;
  return <section style={{ ...placement, position: "relative", height: "100%", display: "flex", flexDirection: direction, alignItems: "center", justifyContent: "center", gap: 9, padding: 12 }} className={`seat table-seat seat-${position} ${seat === HUMAN ? "seat-human" : ""} ${player.melds.length ? "has-melds" : ""} ${game.status === "active" && game.turn === seat ? "turn" : ""} ${onboarding ? "tutorial-highlight" : ""}`}>
    <div className="seat-identity" style={identityStyle}><strong>{name(seat)}</strong></div>
    <div className="player-tile-line">{rack}{declared}</div>
  </section>;
}

const tutorial = [
  ["Welcome to Mahjong", "You are joining a four-player tile game. Mahjong is played through directional rounds; each round begins with a different direction and can have its own rules. Your goal is to make a valid 14-tile Mahjong hand before anyone else."],
  ["This is the East Round", "This game begins with the East Round. You are East at the bottom; South is on your right, West faces you, and North is on your left. East takes the first turn, begins with one extra tile, and therefore discards first."],
  ["The 144 tiles", "The full set has 108 numbered tiles, 16 Winds, 12 Dragons, and 8 bonus tiles. Bamboo, Characters, Dots, Winds, and Dragons build your hand. Flowers and Seasons go to the bonus area and are replaced from the Flower Wall."],
  ["Building the table", "The 144 tiles are shuffled. East separates the Flower Wall, then 13 tiles are dealt to every player. East receives a 14th tile. The remaining tiles form the Draw Wall; Flowers and Seasons are moved to the bonus area and replaced from the Flower Wall."],
  ["Your objective", "A winning East Round hand has four three-tile groups and one two-tile pair. You will slowly improve incomplete groups while keeping a useful pair."],
  ["The building blocks", "These are the only group patterns this MVP supports from the supplied rulebook. Look at the tiles—not just the names—to see what makes each pattern valid."],
  ["How scoring works", "Everyone starts at 35,000. When someone declares Mahjong, the game records the East Round score. Flowers and Seasons can add separate bonus awards when their documented combinations are collected. The final result screen explains the score after a hand ends."],
  ["How your turn works", "East begins with 14 tiles and discards one. After that, players draw one tile, consider their hand, and discard one. A discarded tile may be claimed only when it makes a supported pattern. The Coach will help you through every decision."],
] as const;

